const redact = (value) => String(value ?? "")
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, "[correo-redactado]")
  .replace(/\+?\d[\d\s-]{6,}\d/g, "[telefono-redactado]");
const maskedSender = $json.verifiedSender?.normalized ? String($json.verifiedSender.normalized).slice(0, 4) + "***" : null;
const sanitized = {
  correlationId: $json.conversation?.correlationId,
  sender: maskedSender,
  inboundText: redact($json.inboundText),
  rawBody: redact($json.replayBodyRaw),
  llmResult: $json.llmResult,
  botRequest: $json.botRequest,
  botResponse: $json.botResponse,
  storedAtUtc: new Date().toISOString()
};
return [{ json: { ...$json, redactedReplay: sanitized } }];
